<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal();$pdo=db();$pageTitle='Estoque';$msg='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pid=(int)$_POST['produto_id'];$q=number_value($_POST['quantidade']??0);$tipo=$_POST['tipo']??'Ajuste';$obs=trim($_POST['observacao']??'');if($q<=0)$error='Informe uma quantidade maior que zero.';else{try{$delta=($tipo==='Entrada'||$tipo==='Compra'||$tipo==='Devolução')?$q:-$q;stock_move($pid,$delta,$tipo,'ajuste',null,current_user()['id'],$obs);log_action('movimentação de estoque','produtos',$pid,$tipo.' '.$q);flash('success','Estoque atualizado com sucesso.');redirect('index.php');}catch(Throwable $e){$error=$e->getMessage();}}}
$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT p.*,c.nome categoria_nome FROM produtos p LEFT JOIN categorias c ON c.id=p.categoria_id WHERE p.ativo=1 AND (p.nome LIKE ? OR p.codigo LIKE ? OR p.codigo_barras LIKE ?) ORDER BY p.nome');$x="%$q%";$st->execute([$x,$x,$x]);$rows=$st->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><h1>Estoque</h1><a class="btn secondary" href="movimentacoes.php">Histórico de movimentações</a></div><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><div class="card"><form class="search-row"><input name="q" value="<?=e($q)?>" placeholder="Pesquisar produto"><button class="btn secondary">Pesquisar</button></form></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Estoque</th><th>Mínimo</th><th>Situação</th><th>Movimentar</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?=e($r['nome'])?></strong><div class="muted"><?=e($r['codigo'])?></div></td><td><?=e($r['estoque'])?> <?=e($r['unidade'])?></td><td><?=e($r['estoque_minimo'])?></td><td><?=($r['estoque']<=$r['estoque_minimo'])?'<span class="danger-text">Baixo</span>':'<span class="success-text">Normal</span>'?></td><td><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="produto_id" value="<?=$r['id']?>"><select name="tipo"><option>Entrada</option><option>Saída</option><option>Ajuste</option><option>Devolução</option></select><input style="max-width:100px" type="number" name="quantidade" step="0.01" min="0.01" placeholder="Qtd" required><input style="min-width:180px" name="observacao" placeholder="Observação"><button class="btn small primary">Aplicar</button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="empty">Nenhum produto encontrado.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
